import { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const symptomsList = ["fever","cough","headache","stomach_pain","fatigue"];

function HealthForm() {
  const [age, setAge] = useState("");
  const [gender, setGender] = useState("");
  const [selectedSymptoms, setSelectedSymptoms] = useState([]);
  const navigate = useNavigate();

  const toggleSymptom = (s) => {
    setSelectedSymptoms(
      selectedSymptoms.includes(s) ? selectedSymptoms.filter(x=>x!==s) : [...selectedSymptoms,s]
    );
  };

  const submit = async () => {
    const res = await axios.post("http://127.0.0.1:5000/predict", {
      symptoms: selectedSymptoms
    });

    // Save result to local storage
    localStorage.setItem("result", JSON.stringify(res.data));
    navigate("/result");
  };

  return (
    <div style={{padding:"30px"}}>
      <h2>Health Information</h2>

      Age: <input type="number" onChange={e=>setAge(e.target.value)} /><br/><br/>

      Gender:
      <select onChange={e=>setGender(e.target.value)}>
        <option>Select</option>
        <option>Male</option>
        <option>Female</option>
      </select>

      <h3>Select Symptoms</h3>
      {symptomsList.map(s => (
        <div key={s}>
          <input type="checkbox" onChange={()=>toggleSymptom(s)} /> {s}
        </div>
      ))}

      <button onClick={submit}>Submit</button>
    </div>
  );
}

export default HealthForm;
